// Meldet den Node bei DeskOS an (retained), damit er als Geraet auftaucht.
msg.payload = {
    name: 'BME280 (Node-RED)',
    type: 'sensor',
    capabilities: ['sensor'],
    modules: [
        { id: 'env', type: 'sensor', sensors: ['temperature', 'humidity', 'pressure'] }
    ],
    fw: 'node-red'
};
return msg;

// Normalisiert die Ausgabe des BME280-Read-Nodes auf { temperature, humidity, pressure }.
// Verschiedene contrib-Pakete nutzen leicht andere Feldnamen/Einheiten - hier robust abgefangen.
const p = msg.payload || {};
const num = (...keys) => {
    for (const k of keys) {
        const v = p[k];
        if (typeof v === 'number' && !Number.isNaN(v)) return v;
    }
    return undefined;
};

let temperature = num('temperature', 'temperature_C', 'tempc', 'temp', 't');
let humidity = num('humidity', 'humidity_pct', 'rh', 'h');
let pressure = num('pressure', 'pressure_hPa', 'pressure_hpa', 'p');
const pressurePa = num('pressure_Pa', 'pressure_pa');
if (pressure === undefined && pressurePa !== undefined) pressure = pressurePa / 100;
// Falls der Read-Node Pascal statt Hektopascal liefert (> 2000), in hPa umrechnen:
if (pressure !== undefined && pressure > 2000) pressure = pressure / 100;

const out = {};
if (temperature !== undefined) out.temperature = Math.round(temperature * 10) / 10;
if (humidity !== undefined) out.humidity = Math.round(humidity * 10) / 10;
if (pressure !== undefined) out.pressure = Math.round(pressure * 10) / 10;

if (Object.keys(out).length === 0) return null; // nichts Brauchbares gelesen -> nicht senden
msg.payload = out;
return msg;
